{"files":{"normalize.js":"function normalize(text) {
  if (typeof text !== 'string') {
    return '';
  }
  return text.normalize('NFKC')
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();
}
"},"message":"normalize.js implemented: NFKC normalization, lowercase, collapse whitespace to single ASCII space, trim. No accent removal per spec. Ready for tokenizer.js and pipeline.js to consume."}
